function renderAlarms(){$('pageTitle').textContent='🔔 Alarms & Alerts';$('pageSub').textContent='Real-time alarms using your uploaded loud.mp3 with persistent looping and a built-in diagnostics panel.';$('appContent').innerHTML=`<div class="notice"><b>Important:</b> browser notifications are permission-based. Scheduled alarms created by this page are reliable while the site/app is open; a normal website cannot guarantee an alarm after the browser/OS fully suspends it.</div><div class="quick-actions"><button class="primary" onclick="requestNotifications()">🔔 Allow Notifications</button><button onclick="addSundayMockAlarm()">⏰ Add Sunday Mock Alarm</button><button onclick="testAlarm()">🔊 Test Full Alarm</button><button onclick="testAudioDirect()">🎵 Test loud.mp3 Loop</button><button onclick="enableAlarmAudio()">🔓 Unlock Alarm Sound</button><button onclick="stopAlarm()">🛑 Stop Ringing</button></div><div class="card"><h2>🗓️ Full Timetable → Alarms</h2><p class="small">When enabled, every timed block in the official daily timetable becomes a real-time alarm at its start time. Sunday mock blocks are included. Uses IST and your uploaded loud.mp3.</p><div class="quick-actions"><button class="primary" onclick="setTimetableAlarmEnabled(true)">✅ Enable full timetable alarms</button><button onclick="setTimetableAlarmEnabled(false)">⏸ Disable timetable alarms</button></div><div class="notice"><b>Status:</b> ${timetableAlarmEnabled()?'🟢 ON — every timetable start is alarmed':'🔴 OFF — only manually added alarms run'}</div></div><div class="card"><h2>🧪 Alarm Test Center</h2><p class="small">Run each check before relying on alarms. The loop test intentionally keeps ringing until you press Stop.</p><div id="alarmTests" class="test-grid"></div><div class="quick-actions"><button onclick="runAlarmTests()">🧪 Run All Tests</button><button onclick="testNotification()">🔔 Test Notification</button><button onclick="testScheduleTick()">⏰ Test Scheduler</button></div></div><div class="card"><div class="formgrid"><label>Time<input id="aTime" type="time" value="06:30"></label><label>Label<input id="aLabel" value="Start NEET mission"></label><label>Days<select id="aDays"><option value="daily">Every day</option><option value="weekday">Mon–Fri</option><option value="weekend">Sat–Sun</option><option value="sunday">Sunday only</option></select></label><button class="primary" onclick="addAlarm()">Add Alarm</button></div></div><div class="alarm-list">${alarms.map((a,i)=>`<div class="card alarm"><b>${esc(a.time)} — ${esc(a.label)}</b><span class="small">${a.days} • ${a.enabled===false?'OFF':'ON'}</span><div><button onclick="toggleAlarm(${i})">${a.enabled===false?'Enable':'Disable'}</button><button onclick="deleteAlarm(${i})">Delete</button></div></div>`).join('')||'<div class="empty">No alarms yet.</div>'}</div>`;scheduleAlarms()}
function addAlarm(){alarms.push({time:$('aTime').value,label:$('aLabel').value,days:$('aDays').value,enabled:true});save();renderAlarms()}
function addSundayMockAlarm(){if(!alarms.some(a=>a.time==='07:30'&&a.days==='sunday'&&a.label==='Sunday Full Mock'))alarms.push({time:'07:30',label:'Sunday Full Mock',days:'sunday',enabled:true});save();renderAlarms();requestNotifications()}
function toggleAlarm(i){alarms[i].enabled=alarms[i].enabled===false;save();renderAlarms()}
function deleteAlarm(i){alarms.splice(i,1);save();renderAlarms()}
function testAlarm(){fireAlarm('NEET 2027 test alarm','Notification and audio are working.')}
function timetableAlarmEnabled(){return localStorage.getItem('neet-timetable-alarms')!=='0'}
function setTimetableAlarmEnabled(v){localStorage.setItem('neet-timetable-alarms',v?'1':'0');scheduleAlarms();renderAlarms()}
function getISTNow(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).formatToParts(new Date()).reduce((a,p)=>(a[p.type]=p.value,a),{});const date=`${parts.year}-${parts.month}-${parts.day}`;return {date,hm:`${parts.hour}:${parts.minute}`,second:Number(parts.second),wd:new Date(`${date}T12:00:00`).getDay()}}
function scheduleAlarms(){
 if(window._alarmInterval)clearInterval(window._alarmInterval);
 const tick=()=>{
  const n=getISTNow(), key=`${n.date}-${n.hm}`;
  alarms.forEach(a=>{
   if(a.enabled===false||a.time!==n.hm||localStorage.getItem('alarm-fired-'+key+'-'+a.label))return;
   const ok=a.days==='daily'||(a.days==='weekday'&&n.wd>=1&&n.wd<=5)||(a.days==='weekend'&&(n.wd===0||n.wd===6))||(a.days==='sunday'&&n.wd===0);
   if(ok){localStorage.setItem('alarm-fired-'+key+'-'+a.label,'1');fireAlarm('NEET 2027 • '+a.label,`Day ${selected} — execute your scheduled mission.`)}
  });
  if(timetableAlarmEnabled()){
   const d=days.find(x=>x.date===n.date);
   if(d){
    (d.schedule||[]).forEach((row,i)=>{
     const t=parseScheduleTime(row[0]);
     if(t===null)return;
     const hh=String(Math.floor(t/60)).padStart(2,'0'), mm=String(t%60).padStart(2,'0');
     if(`${hh}:${mm}`!==n.hm)return;
     const key2=`timetable-fired-${n.date}-${n.hm}-${i}`;
     if(localStorage.getItem(key2))return;
     localStorage.setItem(key2,'1');
     fireAlarm(`NEET 2027 • ${d.mock?'MOCK':'TIMETABLE'}`,`⏰ ${row[1]} • Day ${d.day}`);
    });
   }
  }
 };
 tick();
 window._alarmInterval=setInterval(tick,1000);
}
function testNotification(){notify('NEET 2027 • Notification Test','Browser notification permission is working.');alert(Notification.permission==='granted'?'✅ Notification sent.':'⚠️ Notifications are not granted yet.');}
function testScheduleTick(){const n=new Date(),hm=n.toTimeString().slice(0,5);alert(`⏰ Scheduler test passed. Local browser clock: ${hm}. Scheduler checks every second.`);}
function runAlarmTests(){const el=$('alarmTests');if(!el)return;const checks=[['Alarm audio file',!!alarmAudio.src&&alarmAudio.src.endsWith('/loud.mp3'),'Using ./loud.mp3'],['Loop mode',alarmAudio.loop===true,'HTMLAudioElement.loop = true'],['Audio ready',alarmAudio.readyState>=2,`readyState ${alarmAudio.readyState}`],['Notification API','Notification' in window,'Browser API available'],['Notification permission',('Notification' in window&&Notification.permission==='granted'),'Permission granted'],['Scheduler',!!window._alarmInterval,'1-second scheduler active'],['Full timetable alarms',timetableAlarmEnabled(),'Every timetable block is eligible for a start alarm'],['Sunday support',days.some(d=>d.mock&&new Date(d.date+'T12:00:00').getDay()===0),'Mocks include Sundays'],['Day Zero',days.some(d=>d.day===0&&d.date==='2026-09-14'),'14 Sep 2026'],['Day One',days.some(d=>d.day===1&&d.date==='2026-09-15'),'15 Sep 2026'],['Responsive viewport',window.innerWidth>0,'Viewport detected']];el.innerHTML=checks.map(([n,ok,detail])=>`<div class="card test-row"><b>${ok?'✅':'❌'} ${n}</b><span>${esc(detail)}</span></div>`).join('');alarmAudio.load();}
function renderBackup(){$('pageTitle').textContent='💾 Backup / Restore';$('pageSub').textContent='Protect your months of progress.';$('appContent').innerHTML=`<div class="card"><h2>Export</h2><p class="small">Downloads all checks, scorecards, errors, NCERT progress, vaults, alarms and study logs.</p><button class="primary" onclick="exportData()">Download Backup JSON</button></div><div class="card"><h2>Import</h2><input id="importFile" type="file" accept="application/json"><p class="small">Importing replaces current local progress.</p></div>`;$('importFile').onchange=e=>importData(e.target.files[0])}
function exportData(){let data={version:2,exportedAt:new Date().toISOString(),checks,scores,mistakes,ncert,alarms,vault,studyLog};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=`neet2027-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)}function importData(file){if(!file)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);Object.assign(checks,x.checks||{});Object.assign(scores,x.scores||{});mistakes.splice(0,mistakes.length,...(x.mistakes||[]));Object.keys(ncert).forEach(k=>delete ncert[k]);Object.assign(ncert,x.ncert||{});alarms.splice(0,alarms.length,...(x.alarms||[]));vault.formula=x.vault?.formula||[];vault.reaction=x.vault?.reaction||[];studyLog.splice(0,studyLog.length,...(x.studyLog||[]));save();alert('Backup restored.');renderBackup()}catch(e){alert('Invalid backup file.')}};r.readAsText(file)}
function renderRevisions(){let rows=[];days.filter(d=>!d.mock).forEach(d=>d.revisions.forEach(r=>rows.push({day:d.day,label:r.label,source:r.sourceDay,topics:Object.entries(r.topics).map(([s,t])=>`${s}: ${t}`).join(' • ')})));rows=rows.slice(0,180);$('pageTitle').textContent='2-3-5-7 Revision Queue';$('pageSub').textContent='Retrieval before rereading.';$('appContent').innerHTML=`<div class="notice">Close notes → recall → answer → correct → record the error → retest.</div><div class="card"><table><thead><tr><th>Due Day</th><th>Pass</th><th>Source</th><th>Topics</th></tr></thead><tbody>${rows.map(r=>`<tr><td>D${r.day}</td><td>${esc(r.label)}</td><td>D${r.source}</td><td>${esc(r.topics)}</td></tr>`).join('')}</tbody></table></div>`}
function renderSettings(){const cfg=getSupabaseConfig()||{};$('pageTitle').textContent='Settings';$('pageSub').textContent='Local + optional permanent Supabase cloud storage • Day Zero: 14 Sep 2026 • Day 1 starts 15 Sep 2026.';$('appContent').innerHTML=`<div class="card"><h2>☁️ Permanent Cloud Storage — Supabase</h2><p>Completed tasks, scorecards, errors, NCERT progress, formula/reaction vaults, alarms, study logs, backlog and Wake Coach settings can be stored in your own Supabase project. Local storage remains the fast offline cache.</p><div id="cloudStatus" class="notice">${cloudUser?`☁️ Connected: ${esc(cloudUser.email||'account')}`:cfg.url?'☁️ Configured — sign in to sync':'⚪ Not configured'}</div><div class="formgrid"><label>Supabase Project URL<input id="sbUrl" placeholder="https://YOUR-PROJECT.supabase.co" value="${esc(cfg.url||'')}"></label><label>Publishable / anon key<input id="sbKey" type="password" placeholder="sb_publishable_… or anon key" value="${esc(cfg.key||'')}"></label></div><div class="quick-actions"><button class="primary" onclick="configureSupabase()">Save Supabase config</button>${cloudUser?`<button onclick="cloudSaveNow()">☁️ Save now</button><button onclick="pullCloudState(true)">↥ Reload cloud</button><button onclick="supabaseSignOut()">Sign out</button>`:''}</div>${supabaseClient&&!cloudUser?`<div class="formgrid"><label>Email<input id="cloudEmail" type="email" placeholder="you@example.com"></label><label>Password<input id="cloudPassword" type="password" placeholder="••••••••"></label></div><div class="quick-actions"><button class="primary" onclick="supabaseSignIn()">Sign in & sync</button><button onclick="supabaseSignUp()">Create account</button></div>`:''}<p class="small">Security: use only the browser-safe publishable/anon key. Never paste a Supabase service_role key here. The supplied SQL uses Auth + Row Level Security so each account can access only its own planner data.</p></div><div class="card"><h2>Mission contract</h2><ul><li>Execute the generated day instead of choosing random chapters.</li><li>Every mistake gets logged, repaired and retested.</li><li>Use accuracy + completion + mock trend, not hours alone.</li><li>Planner date is a planned date and should follow official NTA announcements if they differ.</li></ul><div class="toolbar"><button onclick="window.print()">Print current view</button><button onclick="location.reload()">Reload app</button></div></div><div class="card"><h2>Planner configuration</h2><p>Day 1: <b>${P.meta.start}</b><br>Final planned day: <b>${P.meta.exam}</b><br>Total days: <b>${P.meta.days}</b><br><span class="small">${esc(P.meta.examDateStatus||'')}</span></p><p class="small">Notifications require browser permission. For phone alarms, install the PWA and allow notifications/alarms in the OS where supported.</p></div>`}
function setActive(){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
function render(){setActive();if(view==='today')renderToday();else if(view==='calendar')renderCalendar();else if(view==='progress')renderProgress();else if(view==='mistakes')renderMistakes();else if(view==='ncert')renderNcert();else if(view==='vaults')renderVaults();else if(view==='revisions')renderRevisions();else if(view==='timer')renderTimer();else if(view==='alarms')renderAlarms();else if(view==='wake')renderWakeCoach();else if(view==='backup')renderBackup();else renderSettings();}
$('daySelect').innerHTML=days.map(d=>`<option value="${d.day}">Day ${d.day} — ${d.date}${d.mock?' • MOCK':''}</option>`).join('');$('daySelect').value=selected;$('daySelect').onchange=e=>{selected=+e.target.value;previewMode=selected!==autoDay;view='today';render()};$('todayBtn').onclick=()=>{selected=autoDay;previewMode=false;$('daySelect').value=selected;view='today';render()};$('prevBtn').onclick=()=>{selected=Math.max(0,selected-1);previewMode=selected!==autoDay;$('daySelect').value=selected;render()};$('nextBtn').onclick=()=>{selected=Math.min(totalStudyDays,selected+1);previewMode=selected!==autoDay;$('daySelect').value=selected;render()};$('printBtn').onclick=()=>window.print();$('notifyBtn').onclick=requestNotifications;document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});$('resetBtn').onclick=()=>{if(confirm('Reset all checkboxes and scorecards?')){localStorage.removeItem('neet-checks');localStorage.removeItem('neet-scores');location.reload()}};$('search').oninput=e=>{let q=e.target.value.trim().toLowerCase();if(!q)return;let hit=days.find(d=>JSON.stringify(d).toLowerCase().includes(q));if(hit){selected=hit.day;previewMode=selected!==autoDay;$('daySelect').value=selected;view='today';render()}};
ensureWakeAlarms();
setInterval(()=>{const c=$('liveClock');if(c)c.textContent=liveClockText();const d=day(selected), st=liveScheduleState(d), el=$('liveState');if(el)el.textContent=st.text;const real=days.find(x=>x.date===localDateISO());},1000);
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});scheduleAlarms();render();
